import axios from "axios";
import { useState } from "react";
import { StyledLink, Li, SearchInput, SearchButton } from './Movies.styled.js';

const Movies = () => {
    const [searchQuery, setSearchQuery] = useState('');
    const [searchResults, setSearchResults] = useState([]);
    const [error, setError] = useState(false);
    const [loading, setLoading] = useState(false);

    const handleSearchSubmit = async (event) => {
        event.preventDefault();
        if (!searchQuery.trim()) {
            setSearchResults([]);
            setError(true);
            return;
        }

        setLoading(true);
        try {
            const API_KEY = 'b3fe8ad645f337f3fa9ceb8e5b164aa5'; // Mută cheia API într-un fișier .env
            const url = `https://api.themoviedb.org/3/search/movie?query=${searchQuery}&include_adult=false&language=en-US&page=1&api_key=${API_KEY}`;
            const response = await axios.get(url);
            setSearchResults(response.data.results || []);
            setError(false);
        } catch (error) {
            console.error('Error searching for movies:', error);
            setError(true);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div>
            <form onSubmit={handleSearchSubmit}>
                <SearchInput
                    type="text"
                    value={searchQuery}
                    placeholder="Search for a movie..."
                    onChange={(e) => setSearchQuery(e.target.value)}
                />
                <SearchButton type="submit">Search</SearchButton>
            </form>
            {loading && <div>Loading search results...</div>}
            {error && <div>Error searching for movies. Please try again later.</div>}
            {searchResults.length === 0 && !error && <div>No movies found for your search query.</div>}
            <ul>
                {searchResults.map(movie => (
                    <Li key={movie.id}>
                        <StyledLink to={`/movies/${movie.id}`}>
                            {movie.title || movie.name}
                        </StyledLink>
                    </Li>
                ))}
            </ul>
        </div>
    );
};

export default Movies;
